version: '3.8'

services:
  postgres:
    image: postgres:18-alpine
    restart: unless-stopped
    user: "999:999"
    environment:
      POSTGRES_USER: postgres
      POSTGRES_PASSWORD: postgres
      POSTGRES_DB: infra_dev
    ports:
      - "5432:5432"
    volumes:
      - postgres_data:/var/lib/postgresql/data
      - ./init-db.sql:/docker-entrypoint-initdb.d/01-uuidv7.sql:ro
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U postgres"]
      interval: 10s
      timeout: 5s
      retries: 5
    networks:
      infrafund-network:
        aliases:
          - postgres

  api:
    build:
      context: ..
      dockerfile: deployment/Dockerfile
    restart: unless-stopped
    depends_on:
      postgres:
        condition: service_healthy
    environment:
      # Application Configuration
      INFRA_ENVIRONMENT: ${INFRA_ENVIRONMENT:-development}
      INFRA_DATA_DIR: ${INFRA_DATA_DIR:-/app/data}

      # REST API Configuration
      INFRA_REST_PORT: ${INFRA_REST_PORT:-8080}
      INFRA_REST_DEBUG: ${INFRA_REST_DEBUG:-true}
      INFRA_REST_BODY_LIMIT: ${INFRA_REST_BODY_LIMIT:-10485760}
      INFRA_REST_CONCURRENCY: ${INFRA_REST_CONCURRENCY:-262144}
      INFRA_REST_READ_TIMEOUT: ${INFRA_REST_READ_TIMEOUT:-15s}
      INFRA_REST_WRITE_TIMEOUT: ${INFRA_REST_WRITE_TIMEOUT:-15s}
      INFRA_REST_IDLE_TIMEOUT: ${INFRA_REST_IDLE_TIMEOUT:-60s}
      INFRA_REST_STRICT_ROUTING: ${INFRA_REST_STRICT_ROUTING:-true}
      INFRA_REST_CASE_SENSITIVE: ${INFRA_REST_CASE_SENSITIVE:-false}
      INFRA_REST_REDUCE_MEMORY_USAGE: ${INFRA_REST_REDUCE_MEMORY_USAGE:-true}
      INFRA_REST_DISABLE_STARTUP_MESSAGE: ${INFRA_REST_DISABLE_STARTUP_MESSAGE:-false}
      INFRA_REST_ENABLE_HEALTH_CHECK: ${INFRA_REST_ENABLE_HEALTH_CHECK:-true}
      INFRA_REST_ENABLE_HELMET: ${INFRA_REST_ENABLE_HELMET:-false}
      INFRA_REST_ENABLE_PPROF: ${INFRA_REST_ENABLE_PPROF:-false}
      INFRA_REST_ENABLE_COMPRESS_REQUEST_BODY: ${INFRA_REST_ENABLE_COMPRESS_REQUEST_BODY:-false}
      INFRA_REST_ENABLE_METRICS_MONITORING: ${INFRA_REST_ENABLE_METRICS_MONITORING:-false}
      INFRA_REST_CORS_ALLOW_ORIGINS: ${INFRA_REST_CORS_ALLOW_ORIGINS:-http://localhost:3000,http://127.0.0.1:3000}
      INFRA_REST_CORS_ALLOW_METHODS: ${INFRA_REST_CORS_ALLOW_METHODS:-GET,POST,PUT,DELETE,OPTIONS,PATCH}
      INFRA_REST_CORS_ALLOW_HEADERS: ${INFRA_REST_CORS_ALLOW_HEADERS:-Origin,Content-Type,Accept,Authorization}
      INFRA_REST_RATE_LIMIT_MAX_REQUESTS: ${INFRA_REST_RATE_LIMIT_MAX_REQUESTS:-1000}
      INFRA_REST_RATE_LIMIT_EXPIRATION: ${INFRA_REST_RATE_LIMIT_EXPIRATION:-1m}

      # PostgreSQL Configuration
      INFRA_POSTGRES_HOST: ${INFRA_POSTGRES_HOST:-postgres}
      INFRA_POSTGRES_PORT: ${INFRA_POSTGRES_PORT:-5432}
      INFRA_POSTGRES_USERNAME: ${INFRA_POSTGRES_USERNAME:-postgres}
      INFRA_POSTGRES_PASSWORD: ${INFRA_POSTGRES_PASSWORD:-postgres}
      INFRA_POSTGRES_DATABASE: ${INFRA_POSTGRES_DATABASE:-infra_dev}
      INFRA_POSTGRES_SSLMODE: ${INFRA_POSTGRES_SSLMODE:-disable}
      INFRA_POSTGRES_TIMEZONE: ${INFRA_POSTGRES_TIMEZONE:-UTC}
      INFRA_POSTGRES_MAX_OPEN_CONNS: ${INFRA_POSTGRES_MAX_OPEN_CONNS:-25}
      INFRA_POSTGRES_MAX_IDLE_CONNS: ${INFRA_POSTGRES_MAX_IDLE_CONNS:-5}
      INFRA_POSTGRES_CONN_MAX_LIFETIME: ${INFRA_POSTGRES_CONN_MAX_LIFETIME:-30m}

      # Cookie Configuration
      INFRA_REST_COOKIE_SAME_SITE: ${INFRA_REST_COOKIE_SAME_SITE:-lax}
      INFRA_REST_COOKIE_DOMAIN: ${INFRA_REST_COOKIE_DOMAIN:-}

      # Auth — REQUIRED: generate with `openssl rand -base64 32`
      INFRA_AUTH_JWT_SIGNING_KEY: ${INFRA_AUTH_JWT_SIGNING_KEY}
      # Auth — REQUIRED: Openfort publishable key (pk_test_...)
      INFRA_AUTH_OPENFORT_PUBLISHABLE_KEY: ${INFRA_AUTH_OPENFORT_PUBLISHABLE_KEY}
      # Optional — must be >= 32 chars if set
      INFRA_REST_COOKIE_ENCRYPTION_SECRET_KEY: ${INFRA_REST_COOKIE_ENCRYPTION_SECRET_KEY}

    ports:
      - "8080:8080"
    volumes:
      - app_data:/app/data
    networks:
      - infrafund-network
    healthcheck:
      test: ["CMD", "wget", "--no-verbose", "--tries=1", "--spider", "http://127.0.0.1:8080/health"]
      interval: 30s
      timeout: 3s
      start_period: 10s
      retries: 3

volumes:
  postgres_data:
    driver: local
  app_data:
    driver: local

networks:
  infrafund-network:
    driver: bridge

